class ShardedCache {
  constructor(primaries, replicas) {
    this.primaries = primaries;   // array of N nodes
    this.replicas = replicas;     // replica[i] backs primary[i]
  }

  shardFor(key) {
    return hash(key) % this.primaries.length;   // pick a shard
  }

  async get(key) {
    const i = this.shardFor(key);
    try {
      return await this.primaries[i].get(key);
    } catch {
      return await this.replicas[i].get(key);     // primary down -> replica
    }
  }

  async set(key, value) {
    const i = this.shardFor(key);
    await this.primaries[i].set(key, value);       // write primary only
  }
}
